#include <stdio.h>
#include <stdlib.h>

int cmp(const void *a, const void *b) {
    return *(int*)a - *(int*)b;
}

int main() {
    int N;
    scanf("%d", &N);
    int *A = malloc(N * sizeof(int));
    for (int i = 0; i < N; i++) {
        scanf("%d", &A[i]);
    }
    qsort(A, N, sizeof(int), cmp);

    int *used = calloc(N, sizeof(int));
    int count = 0;

    for (int i = N - 1; i >= 0; i--) {
        if (used[i]) continue;
        int target = 1;
        while (target <= A[i]) target <<= 1;
        // target is smallest power of two > A[i]
        // we need to find complement = target - A[i]
        int need = target - A[i];
        // binary search for need in [0, i-1]
        int lo = 0, hi = i - 1, found = -1;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            if (A[mid] == need && !used[mid]) {
                found = mid;
                break;
            } else if (A[mid] < need) {
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        if (found != -1) {
            used[i] = 1;
            used[found] = 1;
            count++;
        }
    }

    printf("%d\n", count);
    free(A);
    free(used);
    return 0;
}

