                if (is_power_of_2(a[i] + a[j])) {
                    int nmask = mask ^ (1 << i) ^ (1 << j);
                    if (dp[nmask] + 1 > dp[mask]) {
                        // won't work this way, need to think differently
                    }
                }
            }
        }
    }
    // Better: iterate from full mask down
    // dp[mask] = max pairs from balls in mask
    memset(dp, 0, sizeof(dp));
    for (int mask = total - 1; mask >= 0; mask--) {
        // find lowest set bit
        int i = __builtin_ctz(mask);
        if (mask == 0) { dp[0] = 0; continue; }
        dp[mask] = dp[mask ^ (1 << i)]; // don't pair i
