            if ((mask >> j) & 1) {
                if (is_power_of_2(a[i] + a[j])) {
                    int val = 1 + dp[mask ^ (1 << i) ^ (1 << j)];
                    if (val > dp[mask]) dp[mask] = val;
                }
            }
        }
    }
    printf("%d\n", dp[total - 1]);
    return 0;
}

