typedef long long ll;

static int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll *)a;
    ll y = *(const ll *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    ll *A = (ll *)malloc(sizeof(ll) * N);
    for (int i = 0; i < N; i++) scanf("%lld", &A[i]);

    qsort(A, N, sizeof(ll), cmp_ll);

    char *used = (char *)calloc(N, sizeof(char));
    int ans = 0;

    for (int i = N - 1; i >= 0; i--) {
        if (used[i]) continue;

        ll x = A[i];
        ll p = 1;
        while (p <= x) p <<= 1;   // smallest power of 2 greater than x
        ll need = p - x;

        int l = 0, r = i - 1, pos = -1;
        while (l <= r) {
            int m = (l + r) >> 1;
            if (A[m] < need) {
                l = m + 1;
            } else {
                if (A[m] == need && !used[m]) pos = m;
                r = m - 1;
            }
        }

        if (pos == -1) {
            for (int j = l; j <= i - 1 && j >= 0 && j < i && A[j] == need; j++) {
                if (!used[j]) {
                    pos = j;
                    break;
                }
            }
        }

        if (pos != -1) {
            used[i] = used[pos] = 1;
            ans++;
        }
    }

    printf("%d\n", ans);

    free(A);
    free(used);
    return 0;
}

