// Blossom algorithm for general maximum matching
// Returns maximum matching size

struct Blossom {
    int n;
    vector<vector<int>> adj;
    vector<int> mate, par, base;
    vector<bool> blossom, vis;

    Blossom(int n) : n(n), adj(n), mate(n,-1), par(n), base(n), blossom(n), vis(n) {}

    void addEdge(int u, int v) { adj[u].push_back(v); adj[v].push_back(u); }

    int lca(int a, int b) {
        vector<bool> used(n, false);
        while(true) { a = base[a]; used[a] = true; if(mate[a]==-1) break; a = par[mate[a]]; }
        while(true) { b = base[b]; if(used[b]) return b; b = par[mate[b]]; }
    }

    queue<int> q;
    void markPath(int v, int b, int child) {
        while(base[v] != b) { blossom[base[v]] = true; blossom[base[mate[v]]] = true; par[v] = child; child = mate[v]; v = par[mate[v]]; }
    }

    int findPath(int root) {
        fill(vis.begin(),vis.end(),false); fill(par.begin(),par.end(),-1);
        iota(base.begin(),base.end(),0);
        vis[root] = true; while(!q.empty()) q.pop(); q.push(root);
        while(!q.empty()) {
            int v = q.front(); q.pop();
            for(int to : adj[v]) {
                if(base[v]==base[to] || mate[v]==to) continue;
                if(to==root || (mate[to]!=-1 && par[mate[to]]!=-1)) {
                    int curbase = lca(v, to);
                    fill(blossom.begin(),blossom.end(),false);
                    markPath(v, curbase, to); markPath(to, curbase, v);
                    for(int i=0;i<n;i++) if(blossom[base[i]]) { base[i]=curbase; if(!vis[i]) { vis[i]=true; q.push(i); } }
                } else if(par[to]==-1) {
                    par[to] = v;
                    if(mate[to]==-1) return to;
                    to = mate[to]; vis[to]=true; q.push(to);
                }
            }
        }
        return -1;
    }

    int maxMatching() {
        int res = 0;
        for(int v=0;v<n;v++) if(mate[v]==-1) { int p = findPath(v); if(p!=-1) { res++; while(p!=-1) { int pv=par[p], ppv=mate[pv]; mate[p]=pv; mate[pv]=p; p=ppv; } } }
        return res;
    }
};

int main(){
    int n; cin>>n;
