import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] a = new int[n];
        Map<Integer, Integer> freq = new HashMap<>();

        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
            freq.put(a[i], freq.getOrDefault(a[i], 0) + 1);
        }

        int pairs = 0;
        // sort to process smaller numbers first
        Arrays.sort(a);

        for (int x : a) {
            if (freq.get(x) == 0) continue;

            // try to find a match with the smallest power of two >= x+1
            int power = 1;
            while (power <= x) power <<= 1;
            int target = power - x;

            if (target == x) {
                if (freq.get(x) >= 2) {
                    freq.put(x, freq.get(x) - 2);
                    pairs++;
                }
            } else {
                Integer count = freq.get(target);
                if (count != null && count > 0) {
                    freq.put(x, freq.get(x) - 1);
                    freq.put(target, count - 1);
                    pairs++;
                }
            }
        }

        System.out.println(pairs);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();

        TreeMap<Long, Integer> map = new TreeMap<>();
        long maxA = 0;
        for (int i = 0; i < N; i++) {
            long a = fs.nextLong();
            map.put(a, map.getOrDefault(a, 0) + 1);
            if (a > maxA) maxA = a;
        }

        // Enough powers of 2 so that for every a <= maxA,
        // the next higher power of 2 is included.
        ArrayList<Long> powers = new ArrayList<>();
        long p = 1;
        while (p <= maxA * 2L + 1) {
            powers.add(p);
            if (p > Long.MAX_VALUE / 2) break;
            p <<= 1;
        }

        long ans = 0;

        while (!map.isEmpty()) {
            long x = map.lastKey();
            decrement(map, x);

            long targetPower = nextPowerOfTwoStrictlyGreater(x, powers);
            long y = targetPower - x;

            Integer cnt = map.get(y);
            if (cnt != null && cnt > 0) {
                decrement(map, y);
                ans++;
            }
        }

        System.out.println(ans);
    }

    static void decrement(TreeMap<Long, Integer> map, long key) {
        int c = map.get(key);
        if (c == 1) map.remove(key);
        else map.put(key, c - 1);
    }

    static long nextPowerOfTwoStrictlyGreater(long x, ArrayList<Long> powers) {
        int l = 0, r = powers.size() - 1;
        while (l < r) {
            int m = (l + r) >>> 1;
            if (powers.get(m) > x) r = m;
            else l = m + 1;
        }
        return powers.get(l);
    }
}

