import sys
from collections import Counter

def main():
    input = sys.stdin.readline
    N = int(input())
    A = list(map(int, input().split()))

    cnt = Counter(A)
    ans = 0

    # Process values from large to small.
    # For each x, try to pair it with y so that x + y is a power of two.
    # Choosing the smallest possible power of two greater than x is sufficient:
    # if x is the current largest remaining value, then any partner y must satisfy y <= x,
    # hence x + y < 2x unless y = x, and the relevant target is the next power of two.
    for x in sorted(cnt.keys(), reverse=True):
        while cnt[x] > 0:
            p = 1
            while p <= x:
                p <<= 1
            y = p - x

            if y == x:
                if cnt[x] >= 2:
                    cnt[x] -= 2
                    ans += 1
                else:
                    break
            else:
                if cnt[y] > 0:
                    cnt[x] -= 1
                    cnt[y] -= 1
                    ans += 1
                else:
                    break

    print(ans)

if __name__ == "__main__":
    main()
